window.RP_SESSION={"id":"S-d477a63721ae","messages":[{"id":"RP-II-0155683","time":"2026-08-18T11:13:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"챙-  깡.\n\n날카로운 소리가 황무지에 가득 찬다.","characters":[]},{"id":"RP-II-0155684","time":"2026-08-18T11:17:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"팽.","characters":[]},{"id":"RP-II-0155685","time":"2026-08-18T11:17:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"······","characters":[]},{"id":"RP-II-0155686","time":"2026-08-18T11:17:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"잊고 싶은 그 이름.","characters":[]},{"id":"RP-II-0155687","time":"2026-08-18T11:18:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"용병으로 살며 더러운 꼴을 다 보았다.\n\n헬리오스가 어떻게 그런 생활을 하면서 긍정적으로 살아왔는지가 궁금할 정도로.\n\n망가지고 무너지는 상황들 속에서 여전히 자랑스럽다는 표정을 지은 그가.\n\n너무나도 증오스러웠을 때의 이야기.","characters":[]},{"id":"RP-II-0155688","time":"2026-08-18T11:20:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"살겠다고 몸부림 쳐대는 살덩이들을,\n\n도와달라고 뭉개진 손들을 내미는 피부들을,\n\n가득히 물기를 머금고 고함쳐대는 동공들을,","characters":[]},{"id":"RP-II-0155689","time":"2026-08-18T11:21:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그 모든 것들을 여전히 자애로운 눈으로 바라보고 검을 내려치는 헬리오스,\n\n··· 그것이.","characters":[]},{"id":"RP-II-0155690","time":"2026-08-18T11:21:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그것이 너무나도 증오스러웠을 때,\n\n나의 이름은 ‘팽’ 이었다.","characters":[]},{"id":"RP-II-0155691","time":"2026-08-18T11:30:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"조부모님이 그 두 손으로 넘겨준 가위는 탐스럽게 빛나왔다.\n\n모두에게 관심을 받을 수 있는 이것을 단순히 재단용으로 사용하던 조부모를 한심스럽게 보던 나는 북부를 떠나 헬리오스가 존재하던 용병단으로 들어갔고.\n\n익숙했던 가위의 도움으로 인해 재빠르게 이름을 퍼트리고는 했다.","characters":[]},{"id":"RP-II-0155692","time":"2026-08-18T11:39:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"재단을 위한 가위는 한 번 다른 것을 자르고 나서부터는 본래의 일을 해내지 못한다고 했던가.","characters":[]},{"id":"RP-II-0155693","time":"2026-08-18T11:42:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"살, 근육, 신경, 뼈, 모든 것을 날카롭게 썰어내던 가위의 부분은 더는 천을 자르고자 하지 않았다.\n\n부드러운 천을 자르기보다는 단단하게 자리한 조직을 자르고 싶어했고.\n\n실밥들을 도려내기보다는 튀어나오는 타겟들을 위해 달려가길 바랬다.","characters":[]},{"id":"RP-II-0155694","time":"2026-08-18T12:15:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"가위의 단면은 더 이상 누군가를 감싸안을 보호구를 만들고자 하지 않았고,","characters":[]},{"id":"RP-II-0155695","time":"2026-08-18T12:15:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"본디 제 이름인 맥스 칼립소는 천천히 잊혀져갔다.","characters":[]},{"id":"RP-II-0155696","time":"2026-08-18T12:16:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 맥스, 내가 너무 성가시게 하나? ”\n\n굳건하고도 부드러운 목소리가 귓가를 일렁였다. 검고 아름다운 갈기. 인기 많고 사랑받을 것 같은 존재. 헬리오스···.\n\n“ 아닙니다, 단장님. ”\n\n역시 그를 따라 목소리를 내보았으나, 존경받을만한 위엄은 느껴지지도 않았다.","characters":[]},{"id":"RP-II-0155697","time":"2026-08-18T12:16:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"증오스럽다.","characters":[]},{"id":"RP-II-0155698","time":"2026-08-18T12:17:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 눈에서 다 들어나는구만. 다른 용병들처럼 너도 나를 싫어하는군. “\n\n다른 용병들처럼? 놀란 두 눈이 작아지고 눈썹이 올라감을 느끼고 있었다.\n\n” 예? 누가 헬리오스를···. “","characters":[]},{"id":"RP-II-0155699","time":"2026-08-18T12:18:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 아니, 단장님을···. “","characters":[]},{"id":"RP-II-0155700","time":"2026-08-18T12:18:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"용병 모두가 날 싫어하지, 그 한마디. 굳게 잠겨져있던 벽돌이 무너지는 것은 그의 약한 모습 하나만으로도 무너져버렸다.","characters":[]},{"id":"RP-II-0155701","time":"2026-08-18T12:19:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 당신을, 모두가요? ”","characters":[]},{"id":"RP-II-0155702","time":"2026-08-18T14:52:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그래, 모두가. 하며 대답한 헬리오스의 눈은 어째서인지 애처로웠다.","characters":[]},{"id":"RP-II-0155703","time":"2026-08-18T14:57:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"···.","characters":[]},{"id":"RP-II-0155704","time":"2026-08-18T14:57:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"” 단장, 일 많으시다면서요. “","characters":[]},{"id":"RP-II-0155705","time":"2026-08-18T15:02:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"헬리오스가 천천히 눈을 굽혀갔다. 항상 여유가 가득하던 얼굴에는 놀라움과 기쁨이 가득 차서는, 제 초록색의 눈을 바라보았다.\n\n그가 이를 들어내고 방긋 웃은 것이 몇 번이었지? 건배사를 했을 때도, 대화를 하던 때도. 방긋 웃은 적은 없었던 것 같았다. 그리고 이가···. 음, 진실이었고.","characters":[]},{"id":"RP-II-0155706","time":"2026-08-18T15:06:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 그래, 일 많지. 많아. “","characters":[]},{"id":"RP-II-0155707","time":"2026-08-18T15:06:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!운명","characters":[]},{"id":"RP-II-0155708","time":"2026-08-18T15:06:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 3 = 3\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-II-0155709","time":"2026-08-18T15:06:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"······ 아, 누가 또 문을 두드리네요.","characters":[]},{"id":"RP-II-0155710","time":"2026-08-18T15:07:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"과거에 빠져있을 시간을 허용해주지 않는 모양입니다.","characters":[]},{"id":"RP-II-0155711","time":"2026-08-18T15:07:00+09:00","room":"RP II","name":"맥스 칼립소 / 과거 회상 서술","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-II-0155712","time":"2026-08-18T15:07:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
